import subprocess
from pathlib import Path

wt = Path("/Users/steventran/.do_again/selfdev-20261007")

def run(*args):
    return subprocess.run(args, cwd=wt, text=True, capture_output=True, check=True).stdout

print("branch=" + run("git","branch","--show-current").strip())
print("head=" + run("git","rev-parse","HEAD").strip())
print("status:")
print(run("git","status","--porcelain=v1"))

schema = wt / "src/do_again/core/schema.py"
for i, line in enumerate(schema.read_text().splitlines(), 1):
    if "REQUEST_ID_RE" in line:
        print(f"schema:{i}: {line}")

test = wt / "tests/test_operator_progress.py"
if test.exists():
    for i, line in enumerate(test.read_text().splitlines(), 1):
        if "prior-" in line or "next-step" in line or "goal-alpha" in line:
            print(f"test:{i}: {line}")
